export const styles = `:host {
  display: inline-block;
  width: 166px;
  height: 36px;
  vertical-align: middle;
  transform: none !important;
}
button {
  display: block;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  outline: none;
  -webkit-tap-highlight-color: transparent;
  transform: none !important;
}
button:focus-visible {
  outline: 1px solid #dbc48a;
  outline-offset: 3px;
  border-radius: 4px;
}
svg {
  display: block;
  width: 166px;
  height: 36px;
  overflow: visible;
  pointer-events: none;
  transform: none !important;
}
.card-outline,
.card-border-inner,
.card-line-accent,
.gift-body {
  transform: none !important;
}
.dark-aurora-stream {
  animation: dark-aurora-flow 5.6s linear infinite;
  will-change: transform;
}
@keyframes dark-aurora-flow {
  0% { transform: translateX(0); }
  100% { transform: translateX(-180px); }
}
.sliding-beam {
  animation: slide-beam-sweep 4.2s cubic-bezier(0.4, 0, 0.2, 1) infinite;
  will-change: transform, opacity;
}
@keyframes slide-beam-sweep {
  0% { transform: translateX(-110px); opacity: 0; }
  12% { opacity: 1; }
  48% { transform: translateX(45px); opacity: 1; }
  68% { transform: translateX(95px); opacity: 0; }
  100% { transform: translateX(95px); opacity: 0; }
}
.ambient-glow {
  opacity: 0.35;
}
.ribbon-unified-growth-stroke {
  stroke-dasharray: 100;
  stroke-dashoffset: 0;
}
.ribbon-spine-idle {
  opacity: 1;
  transition: opacity 0.25s ease;
}
.ribbon-spine-idle-glow {
  stroke-dasharray: 20 80;
  stroke-dashoffset: 100;
  animation: ribbon-idle-flow 3.2s cubic-bezier(0.4, 0, 0.2, 1) infinite;
  opacity: 0.65;
}
.ribbon-spine-idle-core {
  stroke-dasharray: 10 90;
  stroke-dashoffset: 100;
  animation: ribbon-idle-flow 3.2s cubic-bezier(0.4, 0, 0.2, 1) infinite;
  opacity: 0.85;
}
@keyframes ribbon-idle-flow {
  0% { stroke-dashoffset: 100; opacity: 0; }
  20% { opacity: 0.85; }
  80% { opacity: 0.85; }
  100% { stroke-dashoffset: -100; opacity: 0; }
}
.playing .ribbon-spine-idle {
  opacity: 0;
}
:host(:hover) .ribbon-unified-growth-stroke,
button:hover .ribbon-unified-growth-stroke,
.playing .ribbon-unified-growth-stroke {
  animation: ribbon-unified-grow 0.65s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes ribbon-unified-grow {
  0% { stroke-dashoffset: 100; }
  100% { stroke-dashoffset: 0; }
}
.ribbon-group {
  transform-origin: 12px 28px;
  animation: ribbon-gentle-wave 3.8s ease-in-out infinite;
}
@keyframes ribbon-gentle-wave {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-0.35px); }
}
.gift-box {
  transform-origin: 23px 30px;
  will-change: transform;
}
.gift-lid {
  transform-origin: 10.8px 14.4px;
  will-change: transform;
}
.gift-tag {
  transform-origin: 26.1px 10.4px;
  will-change: transform;
}
:host(:hover) .gift-box,
button:hover .gift-box,
.playing .gift-box {
  animation: gift-box-pop var(--duration, 0.85s) cubic-bezier(0.16, 1, 0.3, 1) both;
}
:host(:hover) .gift-lid,
button:hover .gift-lid,
.playing .gift-lid {
  animation: ticket-lid-pop var(--duration, 0.85s) cubic-bezier(0.16, 1, 0.3, 1) both;
}
:host(:hover) .gift-tag,
button:hover .gift-tag,
.playing .gift-tag {
  animation: gift-tag-sway var(--duration, 0.85s) cubic-bezier(0.16, 1, 0.3, 1) both;
}
@keyframes gift-box-pop {
  0% { transform: translateY(0) scale(1, 1); }
  13% { transform: translateY(0.18px) scale(1.03, 0.95); }
  39% { transform: translateY(-1.1px) scale(0.985, 1.025); }
  65% { transform: translateY(0.1px) scale(1.015, 0.985); }
  83% { transform: translateY(-0.1px) scale(0.998, 1.002); }
  100% { transform: translateY(0) scale(1, 1); }
}
@keyframes ticket-lid-pop {
  0% { transform: translate(0, 0) rotate(0deg); }
  14% { transform: translate(0.1px, 0.2px) rotate(1deg); }
  38% { transform: translate(0.4px, -1.3px) rotate(-13.5deg); }
  50% { transform: translate(0.4px, -1.3px) rotate(-13.5deg); }
  75% { transform: translate(0, 0) rotate(0deg); }
  86% { transform: translate(0.04px, -0.12px) rotate(-1.5deg); }
  100% { transform: translate(0, 0) rotate(0deg); }
}
@keyframes gift-tag-sway {
  0% { transform: rotate(0deg); }
  14% { transform: rotate(-2.5deg); }
  42% { transform: rotate(8.5deg); }
  68% { transform: rotate(-3.5deg); }
  84% { transform: rotate(1.2deg); }
  100% { transform: rotate(0deg); }
}
.star-left {
  transform-origin: 9.55px 11.73px;
  animation: star-twinkle-left 2.2s -0.4s infinite cubic-bezier(0.4, 0, 0.2, 1);
}
.star-right {
  transform-origin: 154.83px 8.87px;
  animation: star-twinkle-right 2.8s -1.4s infinite cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes star-twinkle-left {
  0%, 100% { transform: scale(0.85); opacity: 0.55; }
  50% { transform: scale(1.22); opacity: 1; filter: drop-shadow(0 0 1px #F4D8AE); }
}
@keyframes star-twinkle-right {
  0%, 100% { transform: scale(0.8); opacity: 0.45; }
  50% { transform: scale(1.24); opacity: 1; filter: drop-shadow(0 0 1px #EACB9E); }
}
.sparkle {
  animation: sparkle-glow 3.4s infinite ease-in-out;
}
.sparkle-bottom {
  animation-delay: -1.7s;
}
@keyframes sparkle-glow {
  0%, 100% { opacity: 0.45; }
  50% { opacity: 0.95; }
}
.gold-rule {
  animation: gold-line-glow 3.0s ease-in-out infinite;
}
@keyframes gold-line-glow {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 0.95; }
}
.motion-paused .dark-aurora-stream,
.motion-paused .sliding-beam,
.motion-paused .ambient-glow,
.motion-paused .ribbon-unified-growth-stroke,
.motion-paused .ribbon-spine-idle-glow,
.motion-paused .ribbon-spine-idle-core,
.motion-paused .ribbon-group,
.motion-paused .gift-box,
.motion-paused .gift-lid,
.motion-paused .gift-tag,
.motion-paused .star,
.motion-paused .sparkle,
.motion-paused .gold-rule {
  animation-play-state: paused !important;
}
@media (prefers-reduced-motion: reduce) {
  .dark-aurora-stream,
  .sliding-beam,
  .ambient-glow,
  .ribbon-unified-growth-stroke,
  .ribbon-spine-idle-glow,
  .ribbon-spine-idle-core,
  .ribbon-group,
  .gift-box,
  .gift-lid,
  .gift-tag,
  .star,
  .sparkle,
  .gold-rule {
    animation: none !important;
  }
}`;

export class SipplayRewardTicket extends HTMLElement {
  static observedAttributes = ['label', 'duration'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' }).innerHTML = `<style>${styles}</style><button type="button">${ticketArt}</button>`;
    this.button = this.shadowRoot.querySelector('button');
    this.lid = this.shadowRoot.querySelector('.gift-lid');
    this.reduced = matchMedia('(prefers-reduced-motion: reduce)');

    this.button.addEventListener('mouseenter', () => this.play());
    this.button.addEventListener('click', () => this.play());

    this.button.addEventListener('animationend', (e) => {
      if (e.animationName === 'ticket-lid-pop') {
        this.finish();
      }
    });

    this.onReduced = () => {
      if (this.reduced.matches) this.finish();
    };
    this.running = false;
  }

  connectedCallback() {
    this.sync();
    this.reduced.addEventListener('change', this.onReduced);
  }

  disconnectedCallback() {
    this.finish();
    this.reduced.removeEventListener('change', this.onReduced);
  }

  attributeChangedCallback() {
    this.sync();
  }

  sync() {
    if (!this.button) return;
    this.button.setAttribute('aria-label', this.getAttribute('label') || '邀请奖励卡券');
    const duration = Math.max(0.4, Math.min(3, Number(this.getAttribute('duration')) || 0.85));
    this.style.setProperty('--duration', `${duration}s`);
  }

  play() {
    if (this.reduced.matches) return;

    if (this._finishTimer) {
      clearTimeout(this._finishTimer);
      this._finishTimer = null;
    }

    const animTargets = this.shadowRoot.querySelectorAll('.gift-box, .gift-lid, .gift-tag, .ribbon-unified-growth-stroke');
    animTargets.forEach(el => {
      el.style.animation = 'none';
    });
    void this.button.offsetWidth;
    animTargets.forEach(el => {
      el.style.animation = '';
    });

    this.button.classList.remove('playing');
    void this.button.offsetWidth;
    this.button.classList.add('playing');
    this.running = true;

    this.dispatchEvent(new CustomEvent('motion-start', { bubbles: true, composed: true }));

    const dur = Math.max(0.4, Math.min(3, Number(this.getAttribute('duration')) || 0.85));
    this._finishTimer = setTimeout(() => {
      this.finish();
    }, dur * 1000 + 30);
  }

  pause() {
    this.button.classList.add('motion-paused');
  }

  resume() {
    this.button.classList.remove('motion-paused');
  }

  finish() {
    if (this._finishTimer) {
      clearTimeout(this._finishTimer);
      this._finishTimer = null;
    }
    const wasRunning = this.running;
    this.running = false;
    this.button.classList.remove('playing');
    if (wasRunning) {
      this.dispatchEvent(new CustomEvent('motion-finish', { bubbles: true, composed: true }));
    }
  }
}

if (!customElements.get('sipplay-reward-ticket')) {
  customElements.define('sipplay-reward-ticket', SipplayRewardTicket);
}
